#{
			var dx = mascot.environment.cursor.x - mascot.anchor.x;
			var dy = mascot.anchor.y - mascot.environment.cursor.y;
			var deg = Math.atan2(dy, dx) * 180 / Math.PI;
			(deg >= 40 && deg <= 50) || (deg >= 130 && deg <= 140)
		}

#{
			var dx = mascot.environment.cursor.x - mascot.anchor.x;
			var dy = mascot.anchor.y - mascot.environment.cursor.y;
			var deg = Math.atan2(dy, dx) * 180 / Math.PI;
			var dist = Math.sqrt(dx*dx + dy*dy);
			dist <= 600 && ((deg > -5 && deg < 5) || (deg > 175 || deg < -175))
		}

#{(function(){
			if(mascot.manager===null) return false;
			var others = mascot.manager.getMascotList();
			var mossCnt=0;
			for(var i=0;i < others.size();i++){
				var is=others.get(i).imageSet;
				if(is==='Mosscreep (Orange)'||is==='Mosscreep (White)'||is==='Mossfly (Orange)'||is==='Mossfly (White)') mossCnt++;
			}
			if(mossCnt <= 9) return false;
			var best=null, bestDist=99999;
			for(var i=0;i < others.size();i++){
				var o=others.get(i); if(o===mascot) continue;
				if(!o.affordances.contains('Hunt')) continue;
				var dx=o.anchor.x-mascot.anchor.x;
				var dy=o.anchor.y-mascot.anchor.y;
				var d=Math.sqrt(dx*dx+dy*dy);
				if(d < bestDist){bestDist=d;best=o;}
			}
			return best!==null;
			})()}

#{(function(){
			if(mascot.manager===null) return false;
			var others = mascot.manager.getMascotList();
			var mossCnt=0;
			for(var i=0;i < others.size();i++){
				var is=others.get(i).imageSet;
				if(is==='Mosscreep (Orange)'||is==='Mosscreep (White)'||is==='Mossfly (Orange)'||is==='Mossfly (White)') mossCnt++;
			}
			if(mossCnt <= 15) return false;
			var best=null, bestDist=99999;
			for(var i=0;i < others.size();i++){
				var o=others.get(i); if(o===mascot) continue;
				if(!o.affordances.contains('Hunt')) continue;
				var dx=o.anchor.x-mascot.anchor.x;
				var dy=o.anchor.y-mascot.anchor.y;
				var d=Math.sqrt(dx*dx+dy*dy);
				if(d < bestDist){bestDist=d;best=o;}
			}
			return best!==null;
			})()}

